import re

def remove_multiple_spaces(s: str) -> str:
    return re.sub(r' +', ' ', s)

def is_Two_Alter(s: str) -> bool:
    if len(s) <= 1:
        # Strings of length 0 or 1 are trivially alternating
        return True

    # Check if there are exactly two distinct characters
    distinct_chars = set(s)
    if len(distinct_chars) != 2:
        return False

    # Check alternating pattern: s[i] != s[i+1] for all i
    for i in range(len(s) - 1):
        if s[i] == s[i+1]:
            return False

    return True

def max_sub_array_sum(arr):
    max_ending_here = max_so_far = arr[0]
    for num in arr[1:]:
        max_ending_here = max(num, max_ending_here + num)
        max_so_far = max(max_so_far, max_ending_here)
    return max_so_far

def len_log(words):
    if not words:
        return 0
    return max(len(word) for word in words)

def count_nums(arr):
    def sum_signed_digits(n):
        s = str(abs(n))
        digits = list(map(int, s))
        if n < 0:
            digits[0] = -digits[0]
        return sum(digits)

    return sum(1 for x in arr if sum_signed_digits(x) > 0)

def cycpattern_check(a, b):
    # For each rotation of b, check if it is a substring of a
    n = len(b)
    for i in range(n):
        rotated = b[i:] + b[:i]
        if rotated in a:
            return True
    return False

from typing import List

def parse_nested_parens(paren_string: str) -> List[int]:
    groups = paren_string.split()
    result = []
    for group in groups:
        max_depth = 0
        current_depth = 0
        for char in group:
            if char == '(':
                current_depth += 1
                max_depth = max(max_depth, current_depth)
            elif char == ')':
                current_depth -= 1
        result.append(max_depth)
    return result

def words_in_sentence(sentence):
    def is_prime(n):
        if n < 2:
            return False
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                return False
        return True

    words = sentence.split()
    # Only include words where either the word length or the index (1-based) is prime, but not both.
    filtered_words = [word for idx, word in enumerate(words, start=1)
                      if (is_prime(len(word)) != is_prime(idx))]
    return " ".join(filtered_words)

